import {GOODS,THEMES,MODES,clone,hash,createGame,pick,remaining,visible,counts,rearrange,hint,tick,upgradeGame,starsFor} from './engine.js';
import {CHAPTERS,LEVEL_COUNT,MECHANICS,ACHIEVEMENTS,DECOR,levelSpec,achievementProgress} from './content.js';
import {STORAGE,freshProfile,normalizeProfile,nextTrailLevel,finishDelivery,backup,parseBackup} from './profile.js';
import {playNote,setAmbience} from './audio.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const CROPS=[[60,32,280,350],[398,52,318,318],[777,35,278,345],[1110,72,320,288],[60,390,280,313],[394,400,329,307],[744,410,364,295],[1116,379,307,330],[50,708,307,325],[407,705,309,324],[753,707,290,322],[1090,744,348,290],[40,55,315,305],[430,45,280,320],[800,28,205,343],[1140,26,266,345],[65,408,265,290],[395,430,325,258],[770,395,285,314],[1115,382,300,323],[32,733,320,320],[396,710,316,336],[742,746,335,296],[1143,706,246,345]];
const icons={sound:'<path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="M15 8c2 2 2 6 0 8m3-11c4 4 4 10 0 14"/>',mute:'<path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="m16 9 5 6m0-6-5 6"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="var(--paper)"/><circle cx="16" cy="12" r="2" fill="var(--paper)"/><circle cx="10" cy="18" r="2" fill="var(--paper)"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]}</svg>`;}
export function good(type,extra=''){const r=CROPS[type];if(!r)return '';const expanded=type>=12;return `<span class="good ${expanded?'expansion':''} ${extra}" aria-hidden="true"><svg viewBox="0 0 ${r[2]} ${r[3]}" focusable="false"><svg width="${r[2]}" height="${r[3]}" viewBox="${r.join(' ')}" overflow="hidden"><image href="./assets/${expanded?'goods-expansion':'goods-atlas'}.png" width="${expanded?1447:1448}" height="${expanded?1087:1086}" /></svg></svg></span>`;}
const easternDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const prettyDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'});
const time=s=>`${Math.floor(Math.ceil(s)/60)}:${String(Math.ceil(s)%60).padStart(2,'0')}`;
let profile=freshProfile(),storageAvailable=true;
try{const raw=JSON.parse(localStorage.getItem(STORAGE)||localStorage.getItem('little-local:v1')||'null');profile=normalizeProfile(raw)||profile;}catch{storageAvailable=false;}
let state,history=[],busy=false,paused=false,hintPicks=[],toastTimer,lastTick=performance.now(),prevFocus,flowTimer,pendingImport,earnedThisRound=[];
let offlineReady=false,installPrompt=null;
let mapChapter=Math.floor((nextTrailLevel(profile)-1)/50),journalTab='shop';
const sessionKey=(mode,date=easternDate())=>mode==='daily'?`daily:${date}`:mode;
function save(){try{if(state)profile.sessions[sessionKey(state.mode,state.date)]={state,history:state.status==='playing'?history.slice(-80):[]};profile.mode=state?.mode||'cozy';const dailyKeys=Object.keys(profile.sessions).filter(k=>k.startsWith('daily:')).sort().reverse();for(const k of dailyKeys.slice(7))delete profile.sessions[k];localStorage.setItem(STORAGE,JSON.stringify(profile));storageAvailable=true;}catch{storageAvailable=false;}$('#save-status').textContent=storageAvailable?`${navigator.onLine?'Your place is saved on this device':'Offline · your place is saved'} ✓${offlineReady?' · Ready offline':''}`:'Playing without saving · browser storage unavailable';}
function make(mode,round=1,options={}){
  const date=easternDate(),levelId=options.levelId||nextTrailLevel(profile);
  return createGame({mode,round:mode==='daily'?3:round,seed:mode==='daily'?hash('little-local:daily:v2:'+date):mode==='trail'?hash('little-local:trail:v2:'+levelId):hash(`${Date.now()}:${Math.random()}:${round}`),theme:mode==='daily'?'market':profile.settings.theme,date,levelId,difficulty:profile.settings.difficulty,surprises:profile.settings.surprises,...options});
}
function loadMode(mode){
  if(!MODES.includes(mode))return;
  if(state)save();const entry=profile.sessions[sessionKey(mode)],restored=upgradeGame(entry?.state);
  state=restored?clone(restored):make(mode);history=restored?(entry.history||[]).map(upgradeGame).filter(Boolean).slice(-80):[];
  paused=false;hintPicks=[];busy=false;earnedThisRound=[];lastTick=performance.now();closeModal();render();save();
  if(state.status==='won')showWin(false);else if(state.status==='timeout')showTimeout();
  else if(mode==='rush'&&!state.started)toast('The clock starts with your first tap. Pause whenever you need.');
  else if(mode==='daily')toast(`${prettyDate(state.date)} · One shared board, as many tries as you like.`);
}
function startLevel(id){
  id=Math.min(LEVEL_COUNT,Math.max(1,Math.trunc(Number(id)||1)));save();state=make('trail',id,{levelId:id});history=[];hintPicks=[];earnedThisRound=[];busy=false;closeModal();render();save();window.scrollTo({top:0,behavior:'instant'});
  const ms=state.spec.mechanics;if(ms.length)toast(ms.map(m=>MECHANICS[m].name).join(' + ')+'. Tap the shelf notes for the rules.',5000);
}
function newRound(mode=state.mode,replay=false){
  if(!replay&&mode==='trail'){if(state.levelId>=LEVEL_COUNT){trailMap(11);return;}startLevel(state.levelId+1);return;}
  state=replay?createGame({mode:state.mode,round:state.round,seed:state.seed,theme:state.theme,date:state.date,levelId:state.levelId||1,difficulty:state.difficulty,surprises:state.surprises,size:state.size}):make(mode,state.mode===mode?state.round+1:1,{size:state.size||144});
  history=[];hintPicks=[];paused=false;busy=false;earnedThisRound=[];lastTick=performance.now();closeModal();render();save();window.scrollTo({top:0,behavior:'instant'});
}
function startPantry(size){save();state=make('pantry',1,{size});history=[];hintPicks=[];busy=false;earnedThisRound=[];closeModal();render();save();toast(`${size} goods. All the time in the world. Your basket stays within reach.`);}

function toast(message,duration=3200){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),duration);}
function announce(message){$('#announcer').textContent=message;}
function applySettings(){const theme=state?.theme||profile.settings.theme;document.body.dataset.theme=theme;document.body.classList.toggle('focus-mode',profile.settings.focus);document.body.classList.toggle('reduce-motion',!profile.settings.motion);document.body.classList.toggle('labels',profile.settings.labels);document.body.classList.toggle('pantry',state?.mode==='pantry');$('#sound-button').innerHTML=icon(profile.settings.sound?'sound':'mute');$('#sound-button').ariaLabel=profile.settings.sound?'Turn sound off':'Turn sound on';$('#sound-button').title=profile.settings.sound?'Sound on':'Sound off';$('#settings-button').innerHTML=icon('settings');}
function render(){
  applySettings();
  $$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===state.mode);b.setAttribute('aria-pressed',b.dataset.mode===state.mode);});
  $('#shop-kicker').textContent=state.mode==='trail'?`CHAPTER ${state.spec.chapterIndex+1} · LEVEL ${state.levelId} / 600`:state.mode==='daily'?`THE DAILY SORT · ${prettyDate(state.date)}`:`${state.mode==='pantry'?'THE GRAND PANTRY':'DELIVERY '+String(state.round).padStart(2,'0')} · ${state.matches} / ${state.total/3} MATCHES`;const theme=THEMES[state.theme];$('#shop-name').textContent=state.mode==='pantry'?'The grand pantry':theme.name;$('#cabinet-sign').textContent=theme.sign;
  $('#round-label').textContent=state.mode==='daily'?'THE DAILY SORT':state.mode==='rush'?'A LIVELIER DELIVERY':state.mode==='trail'?'THE NEIGHBORHOOD TRAIL':state.mode==='pantry'?'THE BIG, SLOW SORT':'MORNING DELIVERY';
  $('#round-number').textContent=state.mode==='daily'?String(new Date(state.date+'T12:00:00').getDate()):state.mode==='pantry'?String(state.total):String(state.round).padStart(2,'0');
  const names=['Fresh beginnings','A familiar rhythm','Room for good things','A little more local','A slower kind of lovely','Fresh from the market'];
  $('#round-name').textContent=state.mode==='daily'?prettyDate(state.date):state.mode==='trail'?state.spec.name:state.mode==='pantry'?'A whole pantry of possibilities':names[(state.round-1)%names.length];
  const percent=Math.round(state.matches*3/state.total*100);
  $('#match-progress').textContent=`${state.matches} of ${state.total/3} matches`;$('#progress-percent').textContent=percent+'%';$('#progress-fill').style.width=percent+'%';$('.progress-track').setAttribute('aria-valuenow',percent);
  $('.cabinet-base>span:first-child').textContent=state.mode==='pantry'?`Scroll the shelves · ${state.shelves.length} in all`:'little local mercantile';$('#stock-count').textContent=`${remaining(state)} little things`;$('#pace-copy').textContent=state.mode==='rush'?'A little hustle, just for fun.':state.mode==='daily'?'The same little puzzle for everyone.':state.mode==='trail'?`Level ${state.levelId} of ${LEVEL_COUNT}. One lovely step.`:'No clock. You’re right on time.';
  renderClock();
  $('#board').classList.toggle('large',state.shelves.length>6);
  $('#board').innerHTML=state.shelves.map((s,si)=>{
    const front=s.rows[0]||[],back=s.rows[1]||[],backCount=s.rows.slice(1).flat().filter(t=>t!==null).length;
    return `<div class="shelf ${s.frosted?'frosted':''} ${s.lock>0?'locked':''}" data-shelf="${si}" aria-label="Shelf ${si+1}${s.lock>0?`, opens after ${s.lock} matches`:''}${backCount?`, ${backCount} items behind`:''}">${backCount?`<div class="backstock">${back.filter(t=>t!==null).map(t=>good(t)).join('')}</div><span class="shelf-stock-number" aria-hidden="true">+${backCount}</span>`:''}${!front.length?'<span class="empty-shelf" aria-hidden="true">all tidy</span>':''}${s.belt||s.frosted?`<span class="shelf-feature" aria-label="${s.belt?'Conveyor shelf':''}${s.frosted?' Frosted back stock':''}">${s.belt?'⇄':''}${s.frosted?'❄':''}</span>`:''}<div class="shelf-items">${Array.from({length:3},(_,slot)=>{
      const t=front[slot];return t==null?'<span class="item empty" aria-hidden="true"></span>':`<button class="item ${hintPicks.some(p=>p.shelf===si&&p.slot===slot)?'hinted':''}" data-shelf="${si}" data-slot="${slot}" data-type="${t}" data-short="${GOODS[t].short}" aria-label="${GOODS[t].name}, shelf ${si+1}, position ${slot+1}" ${s.lock>0||state.tray.length>=7||state.status!=='playing'?'disabled':''}>${good(t)}</button>`;
    }).join('')}</div>${s.lock>0?`<div class="ribbon">⌑ ${s.lock} ${s.lock===1?'match':'matches'} to unwrap</div>`:''}<span class="shelf-label" aria-hidden="true">${String(si+1).padStart(2,'0')}</span></div>`;
  }).join('');
  $('#specials').innerHTML=(state.spec.mechanics||[]).map(m=>`<button class="mechanic-chip" data-mechanic="${m}">${MECHANICS[m].icon} ${MECHANICS[m].name} <span aria-hidden="true">ⓘ</span></button>`).join('')+(state.order?`<div class="order-card ${state.order.fulfilled?'done':state.order.missed?'missed':''}">${good(state.order.type)}<span>${state.order.fulfilled?'A happy little neighbor':state.order.missed?'Your neighbor will be back':'A neighbor’s little order'}<small>${state.order.fulfilled?'+250 points · Thank you!':state.order.missed?'Bonus passed. Keep sorting at your own pace.':`Optional: match ${GOODS[state.order.type].short.toLowerCase()} in the next ${Math.max(0,state.order.within-state.matches)} matches.`}</small></span><span aria-hidden="true">${state.order.fulfilled?'✓':'♡'}</span></div>`:'');
  $('#basket').innerHTML=Array.from({length:7},(_,i)=>`<div class="basket-slot" aria-label="${state.tray[i]===undefined?'Empty basket space':GOODS[state.tray[i]].name}">${state.tray[i]===undefined?'':good(state.tray[i])}</div>`).join('');
  $('#basket').classList.toggle('full',state.tray.length===7);$('#basket-count').textContent=state.tray.length+' / 7';
  $('#basket-message').textContent=state.tray.length===7?'A full basket. Undo or rearrange for free.':state.combo>1?`${state.combo} neat matches in a row. Lovely.`:'Tap 3 of a kind. Make a little room.';
  $('#undo-button').disabled=!history.length||state.status!=='playing';$('#hint-button').disabled=state.status!=='playing'||state.tray.length===7;$('#shuffle-button').disabled=state.status!=='playing';$('#lantern-button').disabled=!state.lanterns||state.status!=='playing'||state.tray.length===7;
  $('#lantern-label').textContent=state.lanterns?`Pack a triple · ${state.lanterns} ${state.lanterns===1?'lantern':'lanterns'}`:'A little help, earned by you';$('#spark-meter').textContent=`${state.spark||0} / 3 matches${state.lanterns>=3?' · full':' to a lantern'}`;
  const cc=counts(state),used=GOODS.map((_,t)=>t).filter(t=>cc[t]>0);
  $('#legend').innerHTML=used.map(t=>`<button class="legend-row" data-legend="${t}" aria-label="Highlight ${GOODS[t].name}, ${cc[t]} remaining including hidden stock">${good(t)}<span>${GOODS[t].short}</span><span>${cc[t]}</span></button>`).join('')||'<p class="modal-copy">Every little thing, in its place.</p>';
  const stamps=profile.completed%3;$('#stamps').innerHTML=Array.from({length:3},(_,i)=>`<span class="stamp ${i<stamps?'filled':''}" aria-label="${i<stamps?'Collected':'Uncollected'} stamp">${i<stamps?'✿':'✳'}</span>`).join('');
  $('#stamps').ariaLabel=`${profile.completed} deliveries completed`;
  $('#stamp-copy').textContent=profile.completed?`${profile.completed} deliveries · ${profile.uniqueGoods} of 24 goods discovered · ${profile.earned.length} keepsakes.`:'Every delivery grows your collection. Twenty-four little goods to discover.';
  $('#footnote').textContent=state.mode==='daily'?`Burlington daily · ${prettyDate(state.date)} · Bests stay on this device.`:state.mode==='trail'?`${CHAPTERS[state.spec.chapterIndex].name} · ${profile.trailStars} trail stars collected`:'Clear the front of a shelf to discover what’s tucked behind.';
}

function renderClock(){const rush=state.mode==='rush'&&!state.clockDisabled,badge=$('#pace-badge');badge.className='pace-badge'+(rush?' rush':'')+(rush&&state.seconds<30?' low':'');badge.innerHTML=rush?`<span aria-hidden="true">◷</span> ${remaining(state)<=3?'Last three · breathe':time(state.seconds)}`:state.mode==='daily'?'<span aria-hidden="true">☀</span> The daily sort':'<span aria-hidden="true">∞</span> Take your time';$('#pause-button').classList.toggle('show',rush);}
function snapshot(){history.push(clone(state));if(history.length>80)history.shift();}
function sound(match=false){playNote(profile.settings,match,state.tray.length);}
function particles(x,y){if(!profile.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<15;i++){const el=document.createElement('span');el.className='particle';el.style.cssText=`left:${x}px;top:${y}px;background:${['#c99d5c','#789674','#b96b55','#e6c77e'][i%4]};--dx:${Math.random()*170-85}px;--dy:${Math.random()*-130+25}px;--rot:${Math.random()*360}deg`;document.body.append(el);setTimeout(()=>el.remove(),850);}}
async function choose(shelf,slot){
  if(busy||paused||$('#modal').open||state.status!=='playing'||state.tray.length>=7)return false;
  const button=$(`.item[data-shelf="${shelf}"][data-slot="${slot}"]`);if(!button)return false;
  const rect=button.getBoundingClientRect(),beforeRows=state.shelves.map(s=>s.rows.length);snapshot();const result=pick(state,shelf,slot);if(!result.ok){history.pop();return false;}
  hintPicks=hintPicks.filter(p=>!(p.shelf===shelf&&p.slot===slot));
  if(result.matched)hintPicks=[];
  sound(result.matched);render();save();
  for(let i=0;i<state.shelves.length;i++)if(state.shelves[i].rows.length<beforeRows[i]&&state.shelves[i].rows.length)$(`.shelf[data-shelf="${i}"]`).classList.add('revealed');
  const slots=$$('.basket-slot'),target=slots[Math.min(state.tray.length,6)].getBoundingClientRect();
  if(profile.settings.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const flying=document.createElement('div');flying.className='flying-good';flying.innerHTML=good(result.type);flying.style.cssText=`left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;height:${rect.height}px`;flying.firstChild.style.cssText='width:100%;height:100%';document.body.append(flying);requestAnimationFrame(()=>requestAnimationFrame(()=>{flying.style.transform=`translate(${target.left-rect.left}px,${target.top-rect.top}px) scale(.6)`;flying.style.opacity='0';}));setTimeout(()=>flying.remove(),330);}
  if(result.matched){$('.basket-wrap').classList.remove('matched');requestAnimationFrame(()=>$('.basket-wrap').classList.add('matched'));particles(rect.left+rect.width/2,rect.top+rect.height/2);announce(`${GOODS[result.type].name} matched. ${state.matches} of ${state.total/3} matches.`);if(state.combo===3||state.combo===6)toast(state.combo===3?'Three lovely matches in a row.':'You’ve found your rhythm. Six in a row.');}
  else announce(`${GOODS[result.type].name} in your basket. ${state.tray.length} of 7 spaces used.`);
  if(result.full)toast('No worries. Undo a tap or rearrange for a fresh start.',5000);
  if(result.unlocked?.length)toast('A ribbon opens. A few more lovely possibilities.');
  for(const i of result.belt||[])$(`.shelf[data-shelf="${i}"]`)?.classList.add('belt-shift');
  if(state.status==='won'){finishRound();showWin(true);}
  // Rerendered buttons preserve keyboard position at the next available shelf item.
  if(document.activeElement===document.body){const next=$(`.item[data-shelf="${shelf}"]:not(:disabled)`)||$('.item:not(:disabled)');next?.focus({preventScroll:true});}
  return true;
}
function undo(){if(!history.length||state.status!=='playing'||paused)return;const elapsed=state.elapsed,seconds=state.seconds,undos=state.undos+1;state=history.pop();state.elapsed=elapsed;state.seconds=seconds;state.undos=undos;hintPicks=[];lastTick=performance.now();render();save();toast('A little room to rethink.');}
function showHint(){if(paused||state.status!=='playing'||state.tray.length===7)return;const h=hint(state);if(h){hintPicks=h.picks;state.hints++;render();save();toast(`Look for ${GOODS[h.type].name.toLowerCase()}.`,3500);}else{toast('The next match is tucked away. Undo, or rearrange for free.',5000);}}
function doRearrange(){if(paused||state.status!=='playing')return;snapshot();rearrange(state);hintPicks=[];render();save();toast('Same little things. A fresh, solvable arrangement.');}
function finishRound(){earnedThisRound=finishDelivery(profile,state);save();render();}
function openModal(html,wide=false){clearTimeout(flowTimer);prevFocus=document.activeElement;$('#modal').classList.toggle('wide',wide);$('#modal-content').innerHTML=html;$('#modal-close').hidden=state.status!=='playing';paused=true;lastTick=performance.now();if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function closeModal(){clearTimeout(flowTimer);if($('#modal').open)$('#modal').close();paused=false;lastTick=performance.now();}

function help(){openModal(`<div class="modal-eyebrow">WELCOME TO LITTLE LOCAL</div><h2 class="modal-title" id="modal-title">Good things come in threes.</h2><div class="modal-art">${good(0)}${good(0)}${good(0)}</div><ol class="steps"><li>Tap identical goods from any shelf. Three of a kind in your basket disappear.</li><li>Empty the front of a shelf to reveal its back stock. The faint goods give you a peek.</li><li>Your basket has seven spaces. If it fills up, Undo or Rearrange is always free.</li></ol><p class="modal-copy">Cozy and Daily have no timer. Rush starts on your first tap, pauses when you step away, and lets you finish the last three in peace.</p><p class="modal-copy">The Trail has 600 replayable levels across 12 chapters. Three matches earn a lantern to pack a triple for you. Lanterns, hints, undo, and rearranging never cost money.</p><p class="modal-copy">Stars reward a clear, avoiding rearranges, and your chain goal or a neighbor’s order. A chain counts consecutive matches made in three taps; taking your time never breaks it.</p><button class="primary-button" data-action="close">Let’s make a little room</button><button class="secondary-button" data-action="settings">Sound & shop settings</button>`);}
function settings(){openModal(`<div class="modal-eyebrow">MAKE YOURSELF AT HOME</div><h2 class="modal-title" id="modal-title">Your kind of cozy.</h2>
${[['sound','Soft little sounds','A gentle note with each tap and match.'],['motion','A little movement','Scooting goods and a sprinkle of confetti.'],['labels','Names on the goods','Extra help telling everything apart.'],['surprises','Little shelf surprises','Ribbons, frost, and conveyors in later Cozy deliveries.'],['flow','Keep the deliveries coming','In Cozy, the next delivery arrives after a 5-second breather.']].map(([key,name,note])=>`<label class="settings-row"><span>${name}<small>${note}</small></span><input type="checkbox" data-setting="${key}" ${profile.settings[key]?'checked':''}></label>`).join('')}
<label class="select-row"><span>A cozy pace<small>Applies to new Cozy deliveries.</small></span><select data-setting="difficulty">${[['gentle','Gentle · familiar goods'],['balanced','Balanced · a little variety'],['brainy','Thoughtful · more to sort']].map(([k,t])=>`<option value="${k}" ${profile.settings.difficulty===k?'selected':''}>${t}</option>`).join('')}</select></label>
<label class="select-row"><span>A little atmosphere<small>Soft, synthesized background sound.</small></span><select data-setting="ambience">${[['off','Quiet shop'],['rain','Soft rain'],['lake','Lake hush']].map(([k,t])=>`<option value="${k}" ${profile.settings.ambience===k?'selected':''}>${t}</option>`).join('')}</select></label>
<label class="select-row"><span>Sound volume</span><input type="range" min="0" max="1" step="0.05" value="${profile.settings.volume}" data-setting="volume" aria-label="Sound volume"></label>
<div class="modal-eyebrow" style="margin-top:24px">YOUR NEXT DELIVERY’S SHOP</div><div class="theme-options">${Object.entries(THEMES).map(([key,t])=>`<button class="theme-option ${profile.settings.theme===key?'selected':''}" data-theme-choice="${key}" aria-pressed="${profile.settings.theme===key}"><span class="swatch" style="background:${t.wood}"></span><span>${t.short}<small>${t.sign.toLowerCase()}</small></span></button>`).join('')}</div><p class="modal-copy compact">New Cozy, Rush, and Pantry deliveries bring your shop’s goods. Trail chapters and the Daily have their own shelves.</p><button class="primary-button" data-action="close">Just right</button><div class="button-pair"><button class="secondary-button" data-action="journal">My shop & keepsakes</button><button class="secondary-button" data-action="backup">Save a backup</button></div><button class="secondary-button" data-action="restart-confirm">Restart this delivery</button>`);}
function scene(label='Your little local'){return `<div class="scene" data-decor="${profile.settings.decor}"><img src="./assets/shop-interior.png" alt="An illustrated Burlington corner shop with wooden shelves, an armchair, and a window looking out over Lake Champlain"><div class="scene-label"><small>A LITTLE VERMONT STATE OF MIND</small><strong>${label}</strong></div></div>`;}
function trailMap(chapter=mapChapter){
  mapChapter=Math.min(11,Math.max(0,chapter));const ch=CHAPTERS[mapChapter],first=mapChapter*50+1,next=nextTrailLevel(profile),chapterWins=Array.from({length:50},(_,i)=>profile.trail[first+i]).filter(Boolean).length,resume=state.mode==='trail'?state:profile.sessions.trail?.state;
  openModal(`${scene('The neighborhood trail')}<div class="trail-overview"><div class="modal-eyebrow">600 LEVELS · 12 LITTLE CHAPTERS<h2 class="modal-title" id="modal-title">Take the long way home.</h2></div><button class="primary-button" ${resume?.status==='playing'&&resume.moves?'data-action="resume-trail"':`data-level="${next}"`}>${resume?.status==='playing'&&resume.moves?`Resume level ${resume.levelId}`:profile.trailWins===600?'Revisit level 600':`Continue at ${next}`} →</button></div><p class="modal-copy compact">${profile.trailWins} / 600 levels sorted · ${profile.trailStars} / 1,800 stars. Every level is open to explore, replay, and make your own.</p><div class="chapter-scroll" aria-label="Trail chapters">${CHAPTERS.map((c,i)=>`<button class="chapter-button ${i===mapChapter?'active':''}" data-chapter="${i}" aria-label="Chapter ${i+1}: ${c.name}" aria-pressed="${i===mapChapter}"><span aria-hidden="true">${c.icon}</span>${i*50+1}–${(i+1)*50}</button>`).join('')}</div><div class="chapter-heading"><h3>${ch.name}</h3><small>${chapterWins} / 50 sorted</small></div><p class="modal-copy compact">${ch.line}</p><div class="level-grid">${Array.from({length:50},(_,i)=>{const id=first+i,r=profile.trail[id],spec=levelSpec(id);return `<button class="level-button ${r?'complete':''} ${id===next?'current':''} ${spec.milestone?'milestone':''}" data-level="${id}" aria-label="Level ${id}: ${spec.name}${r?`, ${r.stars} stars`:''}"><strong>${id}</strong><small aria-hidden="true">${'★'.repeat(r?.stars||0)}${'☆'.repeat(3-(r?.stars||0))}</small></button>`;}).join('')}</div><div class="trail-jump"><span>★ Clear · ★ No rearranges · ★ Chain or order</span><label>Jump to <input id="level-jump" type="number" min="1" max="600" value="${next}" aria-label="Level number"><button data-action="jump">Go</button></label></div><button class="secondary-button" data-action="close">Back to my delivery</button>`,true);
}
function journal(tab=journalTab){
  journalTab=tab;const tabs=`<div class="modal-tabs" aria-label="Shop journal sections">${[['shop','My little shop'],['collection','The collection'],['badges','Keepsakes'],['records','My records']].map(([key,name])=>`<button data-journal="${key}" class="${tab===key?'active':''}" aria-pressed="${tab===key}">${name}</button>`).join('')}</div>`;
  let body='';
  if(tab==='shop')body=`${scene('A shop to grow into.')}<p class="modal-copy compact">${profile.completed} deliveries of little joys. Pick favorite finds in your collection to display here.</p><div class="favorites-shelf">${profile.favorites.length?profile.favorites.map(t=>good(t)).join(''):'<p class="modal-copy">Your first keepsakes are waiting on the shelves.</p>'}</div><div class="modal-eyebrow">A MOOD FOR YOUR LITTLE SHOP</div><div class="decor-grid">${DECOR.map(d=>`<button class="decor-choice ${profile.settings.decor===d.id?'selected':''}" data-decor="${d.id}" ${profile.completed<d.requirement?'disabled':''} aria-pressed="${profile.settings.decor===d.id}"><span aria-hidden="true">${d.icon}</span><strong>${d.name}</strong><small>${profile.completed<d.requirement?`${d.requirement-profile.completed} more deliveries`:'Yours to enjoy'}</small></button>`).join('')}</div><button class="secondary-button" data-action="settings">Sound, atmosphere & shop settings</button>`;
  if(tab==='collection')body=`<p class="modal-copy compact">${profile.uniqueGoods} of 24 goods discovered. Complete deliveries to add their goods. Bronze at 3, silver at 30, gold at 90. Pin up to four favorites to your shop shelf.</p><div class="collection-grid">${GOODS.map((g,t)=>{const n=profile.collection[t],rank=n>=90?'gold':n>=30?'silver':n>=3?'bronze':'unseen',target=n>=90?90:n>=30?90:n>=3?30:3;return `<article class="collection-card ${rank}">${good(t)}<h3>${g.name}</h3><small>${n?`${n} sorted · ${rank}`:'Waiting to be discovered'}</small><p>${g.story}</p><div class="collection-progress" aria-hidden="true"><span style="width:${Math.min(100,n/target*100)}%"></span></div><button data-favorite="${t}" class="${profile.favorites.includes(t)?'selected':''}" ${!n?'disabled':''} aria-pressed="${profile.favorites.includes(t)}">${profile.favorites.includes(t)?'♥ On my shelf':'♡ Pin to my shelf'}</button></article>`;}).join('')}</div>`;
  if(tab==='badges')body=`<p class="modal-copy compact">${profile.earned.length} of ${ACHIEVEMENTS.length} little milestones. A collection of moments, at your own pace.</p><div class="badge-grid">${ACHIEVEMENTS.map(a=>{const r=achievementProgress(profile,a);return `<article class="badge-card ${r.earned?'earned':''}"><span class="badge-icon" aria-hidden="true">${a.icon}</span><strong>${a.name}</strong><p>${a.description}</p><small>${r.earned?'✓ Collected':`${r.value.toLocaleString()} / ${a.goal.toLocaleString()}`}</small><div class="collection-progress" aria-hidden="true"><span style="width:${r.percent}%"></span></div></article>`;}).join('')}</div>`;
  if(tab==='records'){const best=profile.dailyBest[easternDate()];body=`<div class="journal-stats"><div><strong>${profile.completed}</strong><span>deliveries sorted</span></div><div><strong>${profile.totalMatches}</strong><span>happy matches</span></div><div><strong>${profile.bestCombo}</strong><span>best chain</span></div></div><div class="record-list">${[['Trail levels',`${profile.trailWins} / 600`],['Trail stars',`${profile.trailStars} / 1,800`],['Unassisted clears',profile.perfect],['Different Daily dates',profile.dailyDays],['Timed Rush clears',profile.rushWins],['Grand Pantry clears',profile.pantryWins],['Happy neighbor orders',profile.orders]].map(([k,v])=>`<div class="select-row"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><p class="modal-copy">${best?`Today’s Daily best: ${best.moves} taps, ${best.helps} assists, ${time(best.seconds)}.`:'Today’s Daily is waiting for its first little sort.'} All records stay on this device.</p><div class="button-pair"><button class="secondary-button" data-action="backup">Export progress</button><button class="secondary-button" data-action="import">Restore a backup</button></div>`;}
  openModal(`<div class="modal-eyebrow">YOUR LITTLE LOCAL</div><h2 class="modal-title" id="modal-title">A little love adds up.</h2>${tabs}${body}<button class="primary-button" data-action="close">Back to my little shop</button>`,true);
}
function pantryMenu(){openModal(`${scene('The grand pantry')}<div class="modal-eyebrow">A BIGGER, SLOWER SORT</div><h2 class="modal-title" id="modal-title">Stay a little longer.</h2><p class="modal-copy">A cupboard full of possibilities. No timer, no ribbons, no hurry. Scroll the cabinet to explore every shelf. Your basket stays just below it.</p><div class="pantry-options"><button class="pantry-choice" data-pantry="72"><strong>72</strong><small>goods · 8 shelves<br>A lovely little afternoon</small></button><button class="pantry-choice" data-pantry="144"><strong>144</strong><small>goods · 12 shelves<br>The grand pantry tidy</small></button></div>${profile.sessions.pantry?.state.status==='playing'?'<button class="primary-button" data-action="resume-pantry">Resume my saved pantry</button>':''}<p class="modal-copy compact">Starting a new Pantry replaces its saved delivery. Your Cozy, Trail, Daily, and Rush places each stay saved separately.</p><button class="secondary-button" data-action="close">Back to my delivery</button>`);}
function showWin(celebrate){
  const assists=state.hints+state.rearranges+state.undos+(state.magics||0),stars=starsFor(state),daily=state.mode==='daily',trail=state.mode==='trail';
  openModal(`<div class="win-emblem" aria-hidden="true">✿</div><div class="modal-eyebrow">${daily?'TODAY’S DAILY, BEAUTIFULLY SORTED':trail?`TRAIL LEVEL ${state.levelId} COMPLETE`:'DELIVERY COMPLETE'}</div><h2 class="modal-title" id="modal-title">Everything in its place.</h2><div class="star-display" aria-label="${stars} of 3 stars">${'★'.repeat(stars)}<span class="dim">${'★'.repeat(3-stars)}</span></div><p class="modal-copy">${state.mode==='cozy'?'Take a breath. There’s always another little delivery when you’re ready.':daily?'Same shelves, your own little way through. Come back tomorrow for a fresh sort.':trail&&state.levelId===600?'The last stop on the trail. Every corner has a little story now.':state.mode==='pantry'?'So many little things. So much lovely room.':'A little bustle, a lovely finish.'}</p>${!assists?'<span class="perfect">✧ An unassisted clear. Nicely done.</span>':''}<div class="win-stats"><div><strong>${state.matches}</strong><span>MATCHES</span></div><div><strong>${state.score}</strong><span>POINTS</span></div><div><strong>${state.bestCombo}×</strong><span>BEST CHAIN</span></div></div><div class="star-rules">★ Every good sorted<br>${state.rearranges===0?'★':'☆'} No rearranges needed<br>${state.bestCombo>=(state.spec.chainGoal||5)||state.order?.fulfilled?'★':'☆'} A chain of ${state.spec.chainGoal||5}, or a neighbor’s order</div>${earnedThisRound.length?`<div class="earned-note">${earnedThisRound.map(a=>`${a.icon} New keepsake: ${a.name}`).join('<br>')}</div>`:''}<button class="primary-button" data-action="${daily?'share':'next'}">${daily?'Copy my daily result':trail?(state.levelId===600?'Explore the neighborhood':'Next little level →'):'Bring in the next delivery →'}</button><div class="button-pair"><button class="secondary-button" data-action="replay">Try this one again</button><button class="secondary-button" data-action="${trail?'trail':'journal'}">${trail?'The trail map':'My keepsakes'}</button></div>${daily?'<button class="secondary-button" data-action="cozy">Keep playing in Cozy</button>':''}${state.mode==='cozy'&&profile.settings.flow?'<p class="flow-note">A fresh delivery in 5 seconds. <button class="text-button" data-action="stop-flow">Stay a little longer</button></p>':''}`);
  if(celebrate){const r=$('#modal').getBoundingClientRect();particles(r.left+r.width/2,r.top+70);}
  if(state.mode==='cozy'&&profile.settings.flow&&!document.hidden)flowTimer=setTimeout(()=>{if(state.status==='won'&&$('#modal').open&&!document.hidden)newRound();},5000);
}
function mechanicHelp(key){const m=MECHANICS[key];if(!m)return;openModal(`<div class="win-emblem" aria-hidden="true">${m.icon}</div><div class="modal-eyebrow">A LITTLE SHELF SURPRISE</div><h2 class="modal-title" id="modal-title">${m.name}</h2><p class="modal-copy">${m.description}</p><p class="modal-copy compact">There is a way through every starting board. Undo and Rearrange are always here if you want a fresh perspective.</p><button class="primary-button" data-action="close">Back to the little things</button>`);}
async function useLantern(){if(!state.lanterns||paused||busy||state.status!=='playing'||state.tray.length>=7)return;const h=hint(state);if(!h){toast('This triple is tucked away. Undo or rearrange for a fresh view.');return;}state.lanterns--;state.magics++;for(const p of h.picks)if(!await choose(p.shelf,p.slot))break;render();save();if(state.status==='playing')toast('One lovely triple, on the house.');}
const escapeHTML=text=>String(text).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function exportProgress(){save();openModal(`<div class="modal-eyebrow">A KEEPSAKE COPY</div><h2 class="modal-title" id="modal-title">Your little shop, saved.</h2><p class="modal-copy">${profile.completed} deliveries · ${profile.trailWins} Trail levels · ${profile.uniqueGoods} goods discovered. Download a backup file, or copy the text somewhere safe.</p><textarea class="backup-text" id="backup-text" aria-label="Your progress backup" readonly rows="5">${escapeHTML(backup(profile))}</textarea><button class="primary-button" data-action="download-backup">Download JSON backup</button><button class="secondary-button" data-action="copy-backup">Copy backup text</button><button class="secondary-button" data-action="paste-import">Restore from backup text</button><button class="secondary-button" data-action="close">Back to my little shop</button>`);}
function downloadBackup(){const blob=new Blob([backup(profile)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`little-local-${easternDate()}.json`;a.hidden=true;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Backup download requested. You can also copy the text here.');}
async function copyBackup(){const t=$('#backup-text');try{await navigator.clipboard.writeText(t.value);toast('Your backup text is copied.');}catch{t.select();toast('Select and copy the backup text.');}}
function pasteImport(){openModal('<div class="modal-eyebrow">A FAMILIAR LITTLE PLACE</div><h2 class="modal-title" id="modal-title">Bring your shop home.</h2><p class="modal-copy">Paste the complete Little Local backup text below. You can review its progress before restoring.</p><textarea class="backup-text" id="import-text" aria-label="Paste your progress backup" rows="7" placeholder="Paste your backup here…"></textarea><button class="primary-button" data-action="review-import">Review this backup</button><button class="secondary-button" data-action="close">Keep my current shop</button>');}
function reviewImport(text){try{if(text.length>10000000)throw new Error('This backup is too large.');pendingImport=parseBackup(text);openModal(`<div class="modal-eyebrow">WELCOME BACK</div><h2 class="modal-title" id="modal-title">Bring your little shop home?</h2><p class="modal-copy">This backup contains ${pendingImport.completed} deliveries and ${pendingImport.trailWins} completed Trail levels.</p><p class="backup-warning">Restoring replaces the progress on this device. Save a backup of your current shop first if you want to keep both.</p><button class="primary-button" data-action="confirm-import">Restore this backup</button><button class="secondary-button" data-action="backup">Back up my current progress first</button><button class="secondary-button" data-action="close">Keep my current shop</button>`);}catch(error){pendingImport=null;toast(error.message,5500);}}
function showTimeout(){openModal(`<div class="win-emblem" aria-hidden="true">◷</div><div class="modal-eyebrow">THAT WAS A LIVELY LITTLE RUSH</div><h2 class="modal-title" id="modal-title">A little more time?</h2><p class="modal-copy">You sorted ${state.matches} of ${state.total/3} matches. Finish this delivery without the clock, or give the same puzzle another go.</p><button class="primary-button" data-action="untimed">Keep this board, lose the clock</button><button class="secondary-button" data-action="replay">Try Rush again</button>`);}
function pause(){openModal('<div class="win-emblem" aria-hidden="true">☕</div><h2 class="modal-title" id="modal-title">The shop can wait.</h2><p class="modal-copy">Your shelves are right where you left them. The clock is paused.</p><button class="primary-button" data-action="close">I’m ready</button><button class="secondary-button" data-action="settings">Make yourself at home</button>');}
function restartConfirm(){openModal('<div class="modal-eyebrow">A FRESH START</div><h2 class="modal-title" id="modal-title">Restock this delivery?</h2><p class="modal-copy">This puts every item back in its original place. Your other deliveries and journal are saved.</p><button class="primary-button" data-action="replay">Yes, start this delivery again</button><button class="secondary-button" data-action="close">Keep my progress</button>');}
async function share(){const helps=state.hints+state.undos+state.rearranges+(state.magics||0);const result=`Little Local · ${state.date}\n${'🌿'.repeat(Math.min(6,Math.ceil(state.matches/3)))}\n${state.matches} matches · ${state.score} points · ${helps} assists\nA little Vermont state of mind.`;openModal(`<h2 class="modal-title" id="modal-title">Your daily sort.</h2><p class="modal-copy">A little calm to pass along. You can also select and copy the text below.</p><textarea aria-label="Your daily result" readonly rows="6" style="width:100%;font:inherit;font-size:14px;line-height:1.6;padding:14px;border:1px solid var(--line);border-radius:9px;background:#fffaf0;color:var(--ink)">${result}</textarea><button class="primary-button" data-action="share">Copy result text</button><button class="secondary-button" data-action="results">Back to results</button>`);try{await navigator.clipboard.writeText(result);toast('Your daily result is copied. Share a little calm.');}catch{toast('Select the result text to copy it.');$('#modal textarea').select();}}
$('#board').addEventListener('click',e=>{const b=e.target.closest('.item[data-slot]');if(b)choose(Number(b.dataset.shelf),Number(b.dataset.slot));});
$('#board').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;const b=e.target.closest('.item[data-slot]');if(!b)return;e.preventDefault();const buttons=$$('.item:not(:disabled)'),i=buttons.indexOf(b),delta=e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:e.key==='ArrowDown'?6:-6;buttons[(i+delta+buttons.length)%buttons.length]?.focus();});
$$('[data-mode]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.mode==='trail')trailMap(Math.floor(((state.mode==='trail'?state.levelId:nextTrailLevel(profile))-1)/50));else if(b.dataset.mode!==state.mode||state.mode==='daily'&&state.date!==easternDate())loadMode(b.dataset.mode);}));
$('#undo-button').addEventListener('click',undo);$('#hint-button').addEventListener('click',showHint);$('#shuffle-button').addEventListener('click',doRearrange);
$('#help-button').addEventListener('click',help);$('#settings-button').addEventListener('click',settings);$('#shop-button').addEventListener('click',()=>journal('shop'));$('#journal-button').addEventListener('click',()=>journal('records'));$('#pause-button').addEventListener('click',pause);
$('#sound-button').addEventListener('click',()=>{profile.settings.sound=!profile.settings.sound;applySettings();sound(true);save();toast(profile.settings.sound?'A little sound, a little joy.':'A quiet little shop.');});
$('#legend-button').addEventListener('click',()=>toast('Counts include your basket and hidden stock. Tap a good to find visible ones.',5500));
$('#legend').addEventListener('click',e=>{const b=e.target.closest('[data-legend]');if(!b||state.status!=='playing')return;const type=Number(b.dataset.legend);hintPicks=visible(state).filter(p=>p.type===type);render();toast(hintPicks.length?`${hintPicks.length} ${GOODS[type].name.toLowerCase()} on the front shelves.`:`The ${GOODS[type].name.toLowerCase()} is tucked behind, or in your basket.`);});
$('#focus-button').addEventListener('click',()=>{profile.settings.focus=true;render();save();window.scrollTo({top:0,behavior:'instant'});});$('#exit-focus').addEventListener('click',()=>{profile.settings.focus=false;render();save();});$('#install-button').addEventListener('click',installHelp);
$('#trail-button').addEventListener('click',()=>trailMap());$('#pantry-button').addEventListener('click',pantryMenu);$('#collection-button').addEventListener('click',()=>journal('collection'));$('#home-button').addEventListener('click',()=>journal('shop'));$('#lantern-button').addEventListener('click',useLantern);$('#specials').addEventListener('click',e=>{const b=e.target.closest('[data-mechanic]');if(b)mechanicHelp(b.dataset.mechanic);});
$('#modal-close').addEventListener('click',closeModal);$('#modal').addEventListener('cancel',e=>{if(state.status!=='playing')e.preventDefault();});$('#modal').addEventListener('close',()=>{paused=$('#modal').open;lastTick=performance.now();if(!paused&&prevFocus?.isConnected)prevFocus.focus({preventScroll:true});});
$('#modal').addEventListener('click',e=>{
  const a=e.target.closest('[data-action]');
  if(a){const actions={close:()=>state.status==='won'?showWin(false):state.status==='timeout'?showTimeout():closeModal(),settings,journal:()=>journal('shop'),'restart-confirm':restartConfirm,next:()=>newRound(),replay:()=>newRound(state.mode,true),cozy:()=>loadMode('cozy'),share,results:()=>showWin(false),trail:()=>trailMap(),jump:()=>startLevel($('#level-jump').value),'resume-pantry':()=>loadMode('pantry'),'resume-trail':()=>loadMode('trail'),backup:exportProgress,'download-backup':downloadBackup,'copy-backup':copyBackup,'paste-import':pasteImport,'review-import':()=>reviewImport($('#import-text').value),install:async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;}else installHelp();},import:()=>$('#backup-file').click(),'confirm-import':()=>{if(pendingImport){profile=pendingImport;pendingImport=null;state=null;history=[];loadMode(profile.mode);toast('Your little shop is right where you left it.');}},'stop-flow':()=>{clearTimeout(flowTimer);$('.flow-note').textContent='All the time you need. Continue whenever you’re ready.';},untimed:()=>{state.status='playing';state.clockDisabled=true;history=[];closeModal();render();save();toast('All the time you need. Your Cozy delivery is saved separately.');}};actions[a.dataset.action]?.();return;}
  const level=e.target.closest('[data-level]');if(level){startLevel(+level.dataset.level);return;}
  const chapter=e.target.closest('[data-chapter]');if(chapter){trailMap(+chapter.dataset.chapter);return;}
  const tab=e.target.closest('[data-journal]');if(tab){journal(tab.dataset.journal);return;}
  const pantry=e.target.closest('[data-pantry]');if(pantry){startPantry(+pantry.dataset.pantry);return;}
  const theme=e.target.closest('[data-theme-choice]');if(theme&&THEMES[theme.dataset.themeChoice]){profile.settings.theme=theme.dataset.themeChoice;render();save();settings();return;}
  const decor=e.target.closest('[data-decor]');if(decor&&DECOR.some(d=>d.id===decor.dataset.decor&&profile.completed>=d.requirement)){profile.settings.decor=decor.dataset.decor;save();journal('shop');return;}
  const favorite=e.target.closest('[data-favorite]');if(favorite){const t=+favorite.dataset.favorite;if(!profile.collection[t])return;if(profile.favorites.includes(t))profile.favorites=profile.favorites.filter(x=>x!==t);else if(profile.favorites.length>=4){toast('Four little favorites fit here. Unpin one to make a little room.');return;}else profile.favorites.push(t);save();const scroll=$('#modal').scrollTop;journal('collection');$('#modal').scrollTop=scroll;}
});
$('#modal').addEventListener('change',e=>{
  const key=e.target.dataset.setting;
  if(['sound','focus','motion','labels','surprises','flow'].includes(key))profile.settings[key]=e.target.checked;
  else if(key==='volume')profile.settings.volume=Number(e.target.value);
  else if(['difficulty','ambience'].includes(key))profile.settings[key]=e.target.value;else return;
  applySettings();save();if(key==='sound')sound(true);if(['ambience','volume'].includes(key))setAmbience(profile.settings);
});
$('#backup-file').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(file.size>10000000){toast('This file is too large to be a Little Local backup.');return;}try{reviewImport(await file.text());}catch{toast('The file could not be read. Your current progress is safe.');}});
document.addEventListener('keydown',e=>{if($('#modal').open||/INPUT|TEXTAREA/.test(e.target.tagName))return;if(e.key.toLowerCase()==='u'){e.preventDefault();undo();}if(e.key.toLowerCase()==='h'){e.preventDefault();showHint();}if(e.code==='Space'&&e.target===document.body&&state.mode==='rush'){e.preventDefault();pause();}});
document.addEventListener('visibilitychange',()=>{lastTick=performance.now();if(document.hidden){clearTimeout(flowTimer);setAmbience(profile.settings,false);save();}else {setAmbience(profile.settings);if(state.mode==='rush'&&state.started&&state.status==='playing'&&!$('#modal').open)pause();}});
window.addEventListener('blur',()=>{if(state.mode==='rush'&&state.started&&state.status==='playing'&&!$('#modal').open)pause();});
window.addEventListener('pagehide',save);
setInterval(()=>{const now=performance.now(),delta=(now-lastTick)/1000;lastTick=now;if(paused||document.hidden)return;tick(state,Math.min(delta,1));renderClock();if(state.status==='timeout'&&!$('#modal').open){save();showTimeout();}},200);
setInterval(save,5000);
loadMode(MODES.includes(profile.mode)?profile.mode:'cozy');
document.addEventListener('pointerdown',()=>setAmbience(profile.settings),{once:true});

// Optional WebMCP support. These actions use the same state and controls as play.
const context=document.modelContext;
if(context?.registerTool){
  const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
  const read=()=>({mode:state.mode,round:state.round,level:state.levelId,status:state.status,paused,mechanics:state.spec.mechanics,lanterns:state.lanterns,order:state.order,visible:visible(state).map(p=>({...p,name:GOODS[p.type].name})),basket:state.tray.map(t=>GOODS[t].name),matches:state.matches,totalMatches:state.total/3});
  for(const tool of [
    {name:'read_sorting_game',title:'Read the shelves',description:'Read the visible goods, basket, game mode, and progress without changing the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:read},
    {name:'pick_sorting_goods',title:'Pick goods from the shelves',description:'Tap up to three currently visible goods in order, using the same matching rules as the board. Shelf and slot indices start at zero. Stops if the basket fills or the round ends.',inputSchema:{type:'object',properties:{picks:{type:'array',minItems:1,maxItems:3,items:{type:'object',properties:{shelf:{type:'integer',minimum:0,maximum:11},slot:{type:'integer',minimum:0,maximum:2}},required:['shelf','slot'],additionalProperties:false}}},required:['picks'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!Array.isArray(input?.picks)||input.picks.length<1||input.picks.length>3||input.picks.some(p=>!Number.isInteger(p.shelf)||p.shelf<0||p.shelf>11||!Number.isInteger(p.slot)||p.slot<0||p.slot>2))throw new Error('Provide 1–3 valid shelf and slot pairs.');if(paused||state.status!=='playing')throw new Error('Resume the game before picking goods.');let picked=0;for(const p of input.picks){if(!await choose(p.shelf,p.slot))break;picked++;}return {picked,...read()};}},
  ]){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
}

function installHelp(){openModal(`<div class="win-emblem" aria-hidden="true">⌂</div><div class="modal-eyebrow">A LITTLE LOCAL, WHEREVER YOU ARE</div><h2 class="modal-title" id="modal-title">Keep a little calm close.</h2><p class="modal-copy">Open Little Local in Safari on your iPhone. Tap Share, then Add to Home Screen. Keep Open as Web App on, and tap Add.</p><p class="modal-copy compact">Your first visit needs a connection. No account is needed. Once the game says “Ready offline” below, its shelves can come along without a connection. Browser storage can be cleared by your device; export progress from My records for a keepsake copy.</p><p class="modal-copy compact">${offlineReady?'✓ This browser has saved the game for offline play.':'The game is preparing its offline files, if this browser supports them.'}</p>${installPrompt?'<button class="primary-button" data-action="install">Add Little Local to this device</button>':''}<button class="primary-button" data-action="close">Lovely, thank you</button><a class="install-reference" href="https://support.apple.com/guide/iphone/open-as-web-app-iphea86e5236/ios" target="_blank" rel="noopener">Apple’s Home Screen instructions ↗</a>`);}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;save();}).catch(()=>{});}
window.addEventListener('online',save);window.addEventListener('offline',save);
